class Solution:
    def countValidSubarrays(self, nums: List[int], x: int) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            s = 0
            for j in range(i, n):
                s += nums[j]
                fd = s
                while fd >= 10:
                    fd //= 10
                if fd == x and s % 10 == x:
                    ans += 1
        return ans

c.cpp:
class Solution {
public:
    int countValidSubarrays(vector<int>& nums, int x) {
        int n = nums.size();
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            long long s = 0;
            for (int j = i; j < n; j++) {
                s += nums[j];
                long long fd = s;
                while (fd >= 10) fd /= 10;
                if (fd == x && s % 10 == x) ans++;
            }
        }
        return (int)ans;
    }
};

